Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": { "text": "Quanto de cada tipo saiu?", "subtitle": "% do plano do mês · vermelho = atrás do ritmo · clique para filtrar", "anchor": "start", "font": "Segoe UI", "fontSize": 13, "fontWeight": 600, "color": "#3C3C3B", "subtitleFont": "Segoe UI", "subtitleFontSize": 10, "subtitleColor": "#8A8A88", "offset": 4 },
  "data": { "name": "dataset" },
  "transform": [
    { "filter": "datum[''HP Plano do Mês''] > 0" },
    { "calculate": "clamp(datum[''HP % do Plano''], 0, 1)", "as": "pct" },
    { "calculate": "datum[''HP % do Plano''] < datum[''HP % Ritmo Esperado''] ? ''atrás'' : ''em dia''", "as": "situacao" },
    { "calculate": "indexof([''1T'', ''1A'', ''2A'', ''4A''], datum[''Tipo'']) < 0 ? 9 : indexof([''1T'', ''1A'', ''2A'', ''4A''], datum[''Tipo''])", "as": "ordem" },
    { "calculate": "datum[''Tipo''] + ''  '' + format(datum[''HP Plano do Mês''] / 1000, ''.1f'') + ''k''", "as": "rotulo" }
  ],
  "facet": { "column": { "field": "rotulo", "type": "nominal", "sort": { "field": "ordem", "op": "min" }, "title": null,
             "header": { "labelOrient": "bottom", "labelFont": "Segoe UI", "labelFontSize": 11, "labelColor": "#3C3C3B", "labelPadding": 0 } } },
  "spacing": 44,
  "spec": {
    "width": 62, "height": 52,
    "layer": [
      { "mark": { "type": "arc", "innerRadius": 18, "outerRadius": 26, "color": "#E3E3E3" },
        "encoding": { "theta": { "datum": 1, "type": "quantitative", "scale": { "domain": [0, 1] } } } },
      { "params": [ { "name": "__select__", "select": { "type": "point" } } ],
        "mark": { "type": "arc", "innerRadius": 18, "outerRadius": 26, "cursor": "pointer" },
        "encoding": {
          "theta": { "field": "pct", "type": "quantitative", "scale": { "domain": [0, 1] } },
          "color": { "field": "situacao", "type": "nominal", "scale": { "domain": ["atrás", "em dia"], "range": ["#E2000F", "#3C3C3B"] }, "legend": null },
          "opacity": { "condition": { "test": "datum.__selected__ == ''off''", "value": 0.25 }, "value": 1 },
          "tooltip": [
            { "field": "Tipo", "title": "Tipo" },
            { "field": "HP Plano do Mês", "title": "Plano (m)", "format": ",.0f" },
            { "field": "HP % do Plano", "title": "% do plano", "format": ".1%" },
            { "field": "HP % Ritmo Esperado", "title": "Ritmo esperado", "format": ".1%" }
          ] } },
      { "mark": { "type": "text", "font": "Segoe UI", "fontSize": 11, "fontWeight": "bold" },
        "encoding": { "text": { "field": "HP % do Plano", "format": ".0%" },
                      "color": { "field": "situacao", "type": "nominal", "scale": { "domain": ["atrás", "em dia"], "range": ["#E2000F", "#3C3C3B"] }, "legend": null } } }
    ]
  },
  "config": { "view": { "stroke": null }, "padding": { "left": 10, "right": 10, "top": 0, "bottom": 0 } }
}'
